package app

import (
	"fmt"
	"hash/crc32"
	"strings"
	"testing"
)

// Hashes generated by PHP 8.3 password_hash(..., PASSWORD_BCRYPT, ['cost' => 12]) in wormix-api:ref.
var phpHashes = []struct{ plain, hash string }{
	{"secret-alice-1", "$2y$12$ZUPrbgNYax1ya/O300DNvOFWqtTSWcdS/3GY2Ne2cw30UZKcAAZmy"},
	{"пароль123", "$2y$12$.fTb4qxYc/zdfLFQfs1d8ORVIFAsL95FqSO9aw0.teolF9KUcAUrW"},
	{strings.Repeat("x", 80), "$2y$12$4erHM.KywDgxz9F7XqTNseDsOx6BMu/cNWXN017JIYXs2l.1ajcH."}, // > 72 bytes: PHP truncates
}

func TestCheckPHPBcryptHashes(t *testing.T) {
	for _, h := range phpHashes {
		if !CheckPassword(h.plain, h.hash) {
			t.Errorf("PHP hash for %q not accepted", h.plain)
		}
		if CheckPassword(h.plain+"!", h.hash) && len(h.plain) < 72 {
			t.Errorf("wrong password accepted for %q", h.plain)
		}
	}
	if CheckPassword("x", "") {
		t.Error("empty hash must fail")
	}
}

func TestHashPasswordIsPHPCompatible(t *testing.T) {
	h := HashPassword("newpassword")
	if !strings.HasPrefix(h, "$2y$12$") || len(h) != 60 {
		t.Fatalf("hash %q is not a PHP bcrypt hash (cost 12)", h)
	}
	if !CheckPassword("newpassword", h) {
		t.Fatal("own hash rejected")
	}
	// The 'hashed' cast keeps an already-hashed value.
	if hashedCast(h) != h {
		t.Fatal("hashed cast re-hashed a bcrypt hash")
	}
}

func TestSanctumTokenFormat(t *testing.T) {
	// Token from the reference API: "1|" + Str::random(40) + crc32b(entropy); DB stores sha256(random part).
	plain := "ue4TmMDgKhUdA9XFi1AwvhGjfZ9H9QKeFe9IqcXP7744fc50"
	if got := sha256hex(plain); got != "2d31e3d4e6507e2696855c45c3e80577ec4ac5430527139a0d14f335edad4ad9" {
		t.Fatalf("sha256 mismatch: %s", got)
	}
	entropy := plain[:40]
	if got := fmt.Sprintf("%08x", crc32.ChecksumIEEE([]byte(entropy))); got != plain[40:] {
		t.Fatalf("crc32b mismatch: %s vs %s", got, plain[40:])
	}
}
